USE [master]
GO
IF DB_ID(N'BI_VIP_CENTER_FIT_DW_ORIGEN') IS NOT NULL
BEGIN
    ALTER DATABASE [BI_VIP_CENTER_FIT_DW_ORIGEN] SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE [BI_VIP_CENTER_FIT_DW_ORIGEN];
END
GO
CREATE DATABASE [BI_VIP_CENTER_FIT_DW_ORIGEN]
GO
USE [BI_VIP_CENTER_FIT_DW_ORIGEN]
GO
SET NOCOUNT ON;
GO

CREATE TABLE [dbo].[DimFecha](
    [sk_fecha] int NULL,
    [fecha] date NULL,
    [anio] int NULL,
    [trimestre] int NULL,
    [semestre] int NULL,
    [mes] int NULL,
    [nombre_mes] varchar(30) NULL,
    [dia] int NULL,
    [dia_semana] varchar(30) NULL,
    [es_fin_de_semana] bit NULL
)
GO
CREATE TABLE [dbo].[DimCliente](
    [sk_cliente] int IDENTITY(1,1) NOT NULL,
    [id_cliente_bk] int NULL,
    [dni] varchar(20) NULL,
    [nombre_completo] varchar(250) NULL,
    [sexo] varchar(20) NULL,
    [rango_etario] varchar(50) NULL,
    [estado_cliente] varchar(30) NULL,
    [fecha_registro_origen] date NULL,
    [fecha_inicio_validez] date NULL,
    [fecha_fin_validez] date NULL,
    [es_actual] bit NULL
)
GO
CREATE TABLE [dbo].[DimEmpleado](
    [sk_empleado] int IDENTITY(1,1) NOT NULL,
    [id_empleado_bk] int NULL,
    [dni] varchar(20) NULL,
    [nombre_completo] varchar(250) NULL,
    [cargo] varchar(60) NULL,
    [area] varchar(60) NULL
)
GO
CREATE TABLE [dbo].[DimPlan](
    [sk_plan] int IDENTITY(1,1) NOT NULL,
    [id_plan_bk] int NULL,
    [nombre_plan] varchar(60) NULL,
    [duracion_dias] int NULL,
    [precio_referencial] decimal(12,2) NULL,
    [categoria_duracion] varchar(40) NULL
)
GO
CREATE TABLE [dbo].[DimPromocion](
    [sk_promocion] int IDENTITY(1,1) NOT NULL,
    [id_promocion_bk] int NULL,
    [nombre_promocion] varchar(100) NULL,
    [tipo_descuento] varchar(30) NULL,
    [valor_descuento] decimal(12,2) NULL
)
GO
CREATE TABLE [dbo].[FactMembresias](
    [id_membresia_bk] int NULL,
    [sk_cliente] int NULL,
    [sk_plan] int NULL,
    [sk_promocion] int NULL,
    [sk_empleado] int NULL,
    [sk_fecha_inicio] int NULL,
    [sk_fecha_fin] int NULL,
    [duracion_dias] int NULL,
    [precio_final] decimal(12,2) NULL,
    [es_renovacion] bit NULL,
    [estado_membresia] varchar(30) NULL,
    [dias_anticipacion_renovacion] int NULL
)
GO
CREATE TABLE [dbo].[FactVentas](
    [id_pago_bk] int NULL,
    [sk_fecha_pago] int NULL,
    [sk_cliente] int NULL,
    [sk_plan] int NULL,
    [sk_promocion] int NULL,
    [sk_empleado] int NULL,
    [id_membresia_bk] int NULL,
    [monto_neto] decimal(12,2) NULL,
    [descuento_aplicado] decimal(12,2) NULL,
    [precio_lista] decimal(12,2) NULL,
    [metodo_pago] varchar(50) NULL
)
GO
CREATE TABLE [dbo].[FactAsistencias](
    [id_asistencia_bk] int NULL,
    [sk_fecha_asistencia] int NULL,
    [sk_cliente] int NULL,
    [sk_plan] int NULL,
    [sk_empleado] int NULL,
    [hora_ingreso] int NULL,
    [cantidad_asistencias] int NULL
)
GO
CREATE TABLE [dbo].[FactAvisos](
    [id_aviso_bk] int NULL,
    [sk_fecha_aviso] int NULL,
    [sk_cliente] int NULL,
    [sk_empleado] int NULL,
    [id_membresia_bk] int NULL,
    [dias_antes_vencimiento] int NULL,
    [medio] varchar(30) NULL,
    [estado] varchar(30) NULL
)
GO
CREATE TABLE [dbo].[FactRenovaciones](
    [id_renovacion_bk] int NULL,
    [sk_fecha_renovacion] int NULL,
    [sk_cliente] int NULL,
    [sk_empleado] int NULL,
    [id_membresia_anterior_bk] int NULL,
    [id_membresia_nueva_bk] int NULL,
    [dias_anticipacion] int NULL,
    [monto] decimal(12,2) NULL
)
GO
CREATE TABLE [dbo].[FactObjetivos](
    [id_objetivo_bk] int NULL,
    [sk_fecha_inicio] int NULL,
    [sk_cliente] int NULL,
    [tipo_objetivo] varchar(60) NULL,
    [valor_inicial] decimal(10,2) NULL,
    [valor_objetivo] decimal(10,2) NULL,
    [unidad_medida] varchar(30) NULL,
    [estado] varchar(30) NULL
)
GO
CREATE TABLE [dbo].[FactEvaluaciones](
    [id_evaluacion_bk] int NULL,
    [sk_fecha_evaluacion] int NULL,
    [sk_cliente] int NULL,
    [sk_empleado] int NULL,
    [id_objetivo_bk] int NULL,
    [peso] decimal(8,2) NULL,
    [altura] decimal(8,2) NULL,
    [grasa_corporal] decimal(8,2) NULL,
    [masa_muscular] decimal(8,2) NULL
)
GO
CREATE TABLE [dbo].[FactReclamos](
    [id_reclamo_bk] int NULL,
    [sk_fecha_reclamo] int NULL,
    [sk_cliente] int NULL,
    [sk_empleado] int NULL,
    [categoria] varchar(60) NULL,
    [estado] varchar(30) NULL,
    [fecha_resolucion] datetime2(7) NULL,
    [dias_resolucion] int NULL
)
GO

